 insert into public.projects (id,legacy_id,slug,category,title_hy,description_hy,long_description_hy,features_hy,title_en,description_en,long_description_en,features_en,title_ru,description_ru,long_description_ru,features_ru) values ('40000000-0000-4000-8000-000000000001',1,'private-house-construction','construction','Առանձնատան կառուցապատում','Առանձնատան կառուցապատում՝ հարմարավետ և գործնական բնակելի միջավայրի համար։','Նախագիծը ներկայացնում է առանձնատան կառուցապատման մոտեցում, որտեղ կարևոր են տարածքի ճիշտ կազմակերպումը, աշխատանքների հաջորդականությունն ու որակը։ Ուշադրության կենտրոնում են բնակիչների առօրյա հարմարավետությունը և տան ներդաշնակ կապը շրջակա միջավայրի հետ։',array['Տարածքի արդյունավետ կազմակերպում','Շինարարական աշխատանքների պլանավորում','Նյութերի նպատակային ընտրություն','Հարմարավետ բնակելի միջավայր']::text[],'Private house construction','Construction of a private house for a comfortable, practical living environment.','This project presents an approach to private house construction focused on effective space planning, the sequence of works and quality. Everyday comfort and a harmonious connection between the house and its surroundings are central to the approach.',array['Efficient space planning','Planning construction work','Purposeful material selection','A comfortable living environment']::text[],'Строительство частного дома','Строительство частного дома для комфортной и практичной жилой среды.','Проект представляет подход к строительству частного дома, в котором важны грамотная организация пространства, последовательность и качество работ. В центре внимания — повседневный комфорт жильцов и гармоничная связь дома с окружающей средой.',array['Эффективная организация пространства','Планирование строительных работ','Целесообразный выбор материалов','Комфортная жилая среда']::text[]) on conflict do nothing returning id into imported;
 if imported is null then raise notice 'Skipping existing project: private-house-construction'; return; end if;
