 insert into public.projects (id,legacy_id,slug,category,title_hy,description_hy,long_description_hy,features_hy,title_en,description_en,long_description_en,features_en,title_ru,description_ru,long_description_ru,features_ru) values ('40000000-0000-4000-8000-000000000003',3,'modern-kitchen','furniture','Ժամանակակից խոհանոց','Ժամանակակից խոհանոց՝ զուսպ ձևավորմամբ և մտածված դասավորությամբ։','Խոհանոցի ձևավորման հիմքում առօրյա օգտագործման հարմարավետությունն է։ Աշխատանքային մակերեսները, պահեստավորման հատվածներն ու կահույքի դասավորությունը դիտարկվում են միասին՝ ստեղծելով ամբողջական և ներդաշնակ տարածք։',array['Աշխատանքային գոտիների հարմար դասավորություն','Պահեստավորման մտածված լուծումներ','Զուսպ գույներ և հստակ գծեր','Տարածքին համապատասխան կահույք']::text[],'Modern kitchen','A modern kitchen with understated design and a considered layout.','Everyday usability is at the heart of the kitchen design. Work surfaces, storage areas and furniture layout are considered together to create a cohesive, harmonious space.',array['Convenient arrangement of work zones','Thoughtful storage solutions','Understated colours and clean lines','Furniture suited to the space']::text[],'Современная кухня','Современная кухня со сдержанным оформлением и продуманной планировкой.','В основе оформления кухни — удобство повседневного использования. Рабочие поверхности, зоны хранения и расстановка мебели рассматриваются вместе, формируя цельное и гармоничное пространство.',array['Удобное расположение рабочих зон','Продуманные решения для хранения','Сдержанные цвета и чёткие линии','Мебель с учётом особенностей пространства']::text[]) on conflict do nothing returning id into imported;
 if imported is null then raise notice 'Skipping existing project: modern-kitchen'; return; end if;
